//! MNF10/MNF9 conformance (ADR-007 prototype promotion, Track A).
//! Golden vectors: six model ids, generated by scripts/gen_mnf10_fixtures.py;
//! decode must reproduce the fixture's own generator equation exactly, and
//! the rejection vectors must Err without panic.
use mnf_mans::mnf10::decode_payload;
use std::io::Read;

fn fixture_base() -> String {
    let crate_dir = env!("CARGO_MANIFEST_DIR");
    format!("{crate_dir}/../../tests/conformance")
}

fn read(name: &str) -> Vec<u8> {
    let mut v = Vec::new();
    let path = format!("{}/{}", fixture_base(), name);
    std::fs::File::open(&path)
        .unwrap_or_else(|e| panic!("{name} ({path}): {e}"))
        .read_to_end(&mut v)
        .unwrap();
    v
}

fn decode_file(buf: &[u8]) -> Result<Vec<u8>, mnf_mans::mnf10::Error> {
    assert_eq!(&buf[0..4], b"MNF9", "fixture magic");
    let w = u32::from_le_bytes(buf[4..8].try_into().unwrap());
    let h = u32::from_le_bytes(buf[8..12].try_into().unwrap());
    let plen = u32::from_le_bytes(buf[20..24].try_into().unwrap()) as usize;
    decode_payload(&buf[32..32 + plen], w, h)
}

#[test]
fn mnf9_golden_vectors_all_six_models_exact() {
    for name in [
        "mnf10_const_96x64",
        "mnf10_div1d_96x64",
        "mnf10_rec1_96x64",
        "mnf10_bilin_joint_96x64",
        "mnf10_bilin_nested_96x64",
        "mnf10_piecewise_96x64",
    ] {
        let buf = read(&format!("{name}.mnf10"));
        let expect = read(&format!("{name}.expected.pixels"));
        let px = decode_file(&buf).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(px, expect, "{name}: golden pixels exact");
    }
}

#[test]
fn mnf9_rejection_vectors_error_not_panic() {
    // file-level bad magic IS a rejection at the FILE layer: this pins the
    // fixture side (magic differs); payload-level rejections assert as Err.
    let buf = read("rej_mnf10_bad_magic.mnf10");
    assert_ne!(&buf[0..4], b"MNF9", "bad-magic fixture must differ");
    for name in [
        "rej_mnf10_reserved_id0",
        "rej_mnf10_reserved_id7",
        "rej_mnf10_truncated",
        "rej_mnf10_pw_boundary",
        "rej_mnf10_bad_dindex",
    ] {
        let buf = read(&format!("{name}.mnf10"));
        let r = std::panic::catch_unwind(|| decode_file(&buf));
        assert!(matches!(r, Ok(Err(_))), "{name}: must reject without panic");
    }
}

#[test]
fn mnf9_wire_economy_bounded() {
    // every golden file is TINY (the whole point of exact generative form):
    // 96x64 = 6,144 px = 18,432 raw bytes; a whole-frame exact wire < 128 B.
    for name in [
        "mnf10_const_96x64",
        "mnf10_div1d_96x64",
        "mnf10_rec1_96x64",
        "mnf10_bilin_joint_96x64",
        "mnf10_bilin_nested_96x64",
        "mnf10_piecewise_96x64",
    ] {
        let buf = read(&format!("{name}.mnf10"));
        assert!(buf.len() < 128, "{name}: {} B >= 128", buf.len());
    }
}
